      <table class="tbl" id="decadeTable"></table>
      <p class="small" id="decadeNarrative"></p>
    </div>

    <h2>Era-Based Analysis of Winning Scores</h2>
    <div class="panel" id="eraText"></div>

    <h2>Notable Milestones & Records</h2>
    <div class="panel" id="milestones"></div>

    <h2>Key Takeaways & Forward-Looking Observations</h2>
    <div class="panel" id="conclusions"></div>

    <div class="footer">Source: <code>/app/benchmark/data.csv</code>. All figures in this report are computed directly from the provided CSV (no external estimates).</div>
  </div>

