  "rows": 93,
  "start": 1934,
  "end": 2026,
  "unique_composers": 69,
  "unique_films": 92,
  "max_wins": 4,
  "max_composers": ["John Barry","John Williams","Ludwig Göransson"],
  "repeat_wins": 24,
  "repeat_rate": 25.8064516129,
  "decade_most_unique": 1980,
  "decade_most_unique_count": 10,
  "top_composers": {"John Barry":4,"John Williams":4,"Ludwig Göransson":4,"Alan Menken":3,"Dimitri Tiomkin":3,"Maurice Jarre":3,"Max Steiner":3,"Alexandre Desplat":2,"Alfred Newman":2,"Franz Waxman":2,"Gustavo Santaolalla":2,"Hans Zimmer":2},
  "decade_stats": [
    {"Decade":1930,"ceremonies":6,"unique_winners":6,"repeat_wins":0,"repeat_share":0},
    {"Decade":1940,"ceremonies":10,"unique_winners":7,"repeat_wins":3,"repeat_share":30},
    {"Decade":1950,"ceremonies":10,"unique_winners":8,"repeat_wins":2,"repeat_share":20},
    {"Decade":1960,"ceremonies":10,"unique_winners":8,"repeat_wins":2,"repeat_share":20},
    {"Decade":1970,"ceremonies":10,"unique_winners":8,"repeat_wins":2,"repeat_share":20},
    {"Decade":1980,"ceremonies":10,"unique_winners":10,"repeat_wins":0,"repeat_share":0},
    {"Decade":1990,"ceremonies":10,"unique_winners":8,"repeat_wins":2,"repeat_share":20},
    {"Decade":2000,"ceremonies":10,"unique_winners":9,"repeat_wins":1,"repeat_share":10},
    {"Decade":2010,"ceremonies":10,"unique_winners":8,"repeat_wins":2,"repeat_share":20},
    {"Decade":2020,"ceremonies":7,"unique_winners":5,"repeat_wins":2,"repeat_share":28.5714285714}
  ],
  "longest_gap": {"gap_years":27,"composer":"Hans Zimmer","from":1994,"to":2021},
  "streaks": [["Franz Waxman",1950,1951,2],["Alan Menken",1991,1992,2],["Gustavo Santaolalla",2005,2006,2],["Ludwig Göransson",2023,2024,2]],
  "latest": {"Year":2026,"Film":"Sinners","Composer":"Ludwig Göransson"}
};

const kpi = document.getElementById('kpi');
kpi.innerHTML = `
<div class="card"><div class="k">Total Unique Composers</div><div class="v">${data.unique_composers}</div><div class="small">Across ${data.rows} ceremonies</div></div>
<div class="card"><div class="k">Maximum Wins by One Composer</div><div class="v">${data.max_wins}</div><div class="small">Leaders: ${data.max_composers.join(', ')}</div></div>
<div class="card"><div class="k">Repeat Winner Rate</div><div class="v">${data.repeat_rate.toFixed(1)}%</div><div class="small">${data.repeat_wins} of ${data.rows} ceremonies</div></div>
<div class="card"><div class="k">Decade With Most Unique Winners</div><div class="v">${data.decade_most_unique}s</div><div class="small">${data.decade_most_unique_count} unique winners</div></div>`;

document.getElementById('rows').textContent=data.rows;
document.getElementById('uc').textContent=data.unique_composers;
document.getElementById('uf').textContent=data.unique_films;

const topEntries=Object.entries(data.top_composers);
new Chart(document.getElementById('topBar'),{
  type:'bar',
  data:{labels:topEntries.map(x=>x[0]),datasets:[{label:'Wins',data:topEntries.map(x=>x[1]),backgroundColor:'#f0b90b'}]},
