});

document.getElementById('topTable').innerHTML='<tr><th>Rank</th><th>Composer</th><th>Wins</th></tr>'+topEntries.map((e,i)=>`<tr><td>${i+1}</td><td>${e[0]}</td><td>${e[1]}</td></tr>`).join('');
document.getElementById('topNarrative').textContent=`At the top, three composers are tied at ${data.max_wins} wins each (${data.max_composers.join(', ')}), indicating no single all-time runaway leader in this dataset window. The top tier blends legacy studio-era names and modern franchise-era composers, reflecting both continuity and turnover in Oscar scoring prestige.`;

